import fcntl
import hashlib
import json
import pathlib
import random
import statistics
import subprocess

root = pathlib.Path(__file__).resolve().parents[2]
folder = root / '.verify-helper/cache/wm_small_rank'
folder.mkdir(parents=True,exist_ok=True)
header = (root/'data_structure/wavelet_matrix.hpp').read_text()
quad = (root/'components/quad_bit_vector.hpp').read_text()
component = (root/'components/oct_bit_vector.hpp').read_text()
bench = (root/'test/benchmark/wavelet_matrix_opt.cpp').read_text()
(folder/'source.hpp').write_text(header)
(folder/'component.hpp').write_text(component)
(folder/'quad.hpp').write_text(quad)
(folder/'bench.cpp').write_text(bench)

def finish_calls(s):
    end_scalar = '\t\t}\n\t}\n#if defined(__x86_64__) || defined(__i386__)\n\t__attribute__((target("avx2,popcnt"), always_inline)) static __m256i popcounts'
    assert end_scalar in s
    s = s.replace(end_scalar,end_scalar.replace('\n\t}\n#if','\n\t\tfinish(total);\n\t}\n#if'),1)
    end_vector = '\t\t}\n\t}\n\t__attribute__((target("avx2,popcnt"), always_inline)) Route route_avx2'
    assert end_vector in s
    return s.replace(end_vector,end_vector.replace('\n\t}\n\t__attribute__','\n\t\tfinish(total);\n\t}\n\t__attribute__'),1)

small = component.replace('\tint n;','\tint n;\n\tbool small = false;')
finish = '''\tvoid finish(const std::array<std::uint32_t, 8> &total) {
\t\tsmall = total[3] == std::uint32_t(n);
\t\tif (!small) return;
\t\tfor (auto &b : blocks)
\t\t\tfor (int i = 0; i < 4; ++i) {
\t\t\t\tb.masks[4 + i] = b.masks[i] ^ (i ? b.masks[i - 1] : 0);
\t\t\t\tb.prefix[4 + i] = b.prefix[i] - (i ? b.prefix[i - 1] : 0);
\t\t\t}
\t}
'''
small = small.replace('\texplicit OctBitVector(',finish+'\texplicit OctBitVector(')
small = finish_calls(small)
small = small.replace('unsigned(_mm256_movemask_ps(_mm256_castsi256_ps(passed)))','(unsigned(_mm256_movemask_ps(_mm256_castsi256_ps(passed))) & (small ? 15u : 255u))')
small = small.replace('\t\tif (!digit) return 0;\n\t\tconst auto &b', '\t\tif (!digit) return 0;\n\t\tif (small && digit >= 4) return r;\n\t\tconst auto &b')
small = small.replace('\tint rank(int r, int digit) const {\n\t\tconst auto &b = blocks[r >> 5];','\tint rank(int r, int digit) const {\n\t\tconst auto &b = blocks[r >> 5];\n\t\tif (small) return digit < 4 ? b.prefix[4 + digit] + std::popcount(b.masks[4 + digit] & mask(r)) : 0;')

binary = component.replace('\tint n;', '\tint n;\n\tbool binary = false;')
binary = binary.replace('\texplicit OctBitVector(', '\tvoid finish(const std::array<std::uint32_t, 8> &total) { binary = total[1] == std::uint32_t(n); }\n\texplicit OctBitVector(')
binary = finish_calls(binary)
binary = binary.replace('\tint rank(int r, int digit) const {', '\tint rank(int r, int digit) const {\n\t\tif (binary) {\n\t\t\tint zero = below(r, 1);\n\t\t\treturn digit == 0 ? zero : digit == 1 ? r - zero : 0;\n\t\t}')

variants = {'current':component,'small_exact':small,'binary_rank':binary}
test = r'''#include "components/oct_bit_vector.hpp"
#include <iostream>
#include <random>
int main() {
    if (sizeof(OctBitVector) != 32) return 11;
    std::mt19937 random(713);
    for (int n : {0,1,31,32,33,63,64,65,127}) for (int sigma=1; sigma<=8; ++sigma) for (int shift : {0,3,30}) {
        std::vector<std::uint32_t> a(n);
        for (auto &x:a) x = (random()%sigma) << shift;
        OctBitVector b(n), c(n);
        b.build_scalar(a,shift);
        c.build(a,shift);
        for (int r=0; r<=n; ++r) {
            std::array<int,8> count{};
            for (int i=0;i<r;++i) ++count[(a[i]>>shift)&7];
            auto br = b.ranks(r), cr = c.ranks(r);
            for (int digit=0;digit<8;++digit) {
                int below = 0;
                for (int i=0;i<digit;++i) below += count[i];
                if (b.rank(r,digit)!=count[digit] || c.rank(r,digit)!=count[digit] || br[digit]!=count[digit] || cr[digit]!=count[digit]) return 12;
                if (b.below(r,digit)!=below || c.below(r,digit)!=below) return 13;
            }
        }
        if (!n) continue;
        for (int trial=0;trial<30;++trial) {
            int l=random()%n,r=random()%n;
            if(l>r)std::swap(l,r);
            ++r;
            int k=random()%(r-l);
            std::array<int,8> counts{};
            for (int i=l;i<r;++i)++counts[(a[i]>>shift)&7];
            int d=0,before=0;
            while (before+counts[d]<=k) before += counts[d++];
            auto x=b.route_scalar(l,r,k),y=c.route_scalar(l,r,k);
            if(x.digit!=d || y.digit!=d || x.b-x.a!=counts[d] || y.b-y.a!=counts[d] || x.k!=k-before || y.k!=k-before) return 14;
#if defined(__x86_64__) || defined(__i386__)
            if (OctBitVector::has_avx2()) {
                auto z=c.route_avx2(l,r,k);
                if(z.digit!=d || z.b-z.a!=counts[d] || z.k!=k-before || c.select_avx2(l,r,k)!=d) return 15;
            }
#endif
        }
        std::fill(a.begin(),a.end(),0);
        c.build(a,shift);
        if(c.rank(n,0)!=n || c.rank(n,1)!=0) return 16;
    }
    std::cout << "passed " << sizeof(OctBitVector) << '\n';
}
'''

flags = ['-std=c++23','-O2','-march=native','-ftrivial-auto-var-init=zero','-DATCODER','-DONLINE_JUDGE']
with open('/tmp/cp-wm-opt.lock','w') as lock:
    fcntl.flock(lock,fcntl.LOCK_EX)
    for name, octet in variants.items():
        work = folder / name
        (work/'data_structure').mkdir(parents=True,exist_ok=True)
        (work/'components').mkdir(exist_ok=True)
        (work/'data_structure/wavelet_matrix.hpp').write_text(header)
        (work/'components/oct_bit_vector.hpp').write_text(octet)
        (work/'components/quad_bit_vector.hpp').write_text(quad)
        (work/'bench.cpp').write_text(bench)
        (work/'check.cpp').write_text(test)
        subprocess.run(['g++',*flags,'-I'+str(work),str(work/'check.cpp'),'-o',str(work/'check')],check=True)
        subprocess.run(['taskset','-c','2',str(work/'check')],check=True)
        subprocess.run(['g++',*flags,'-I'+str(work),str(work/'bench.cpp'),'-o',str(work/'bench')],check=True)
    rng = random.Random(20261019)
    raw = {}
    for n in (200000,500000):
        for mode in (6,1,9,0):
            for op in ('count','kth','freq'):
                samples={v:[] for v in variants}
                checks=[]
                for trial in range(4):
                    order=list(variants)
                    rng.shuffle(order)
                    checksum=None
                    for name in order:
                        result=json.loads(subprocess.check_output(['taskset','-c','2',str(folder/name/'bench'),str(n),'200000',str(mode),'0',op,'32',str(713+trial*37)],text=True))
                        if checksum is None:checksum=result['checksum']
                        assert result['checksum']==checksum,(n,mode,op,name)
                        if trial:samples[name].append(result['ms'])
                    checks.append(checksum)
                key=f'{n}/{mode}/{op}'
                raw[key]={'samples_ms':samples,'median_ms':{v:statistics.median(s) for v,s in samples.items()},'checksums':checks}
                print(key,raw[key]['median_ms'],flush=True)
                (folder/'results.json').write_text(json.dumps({'flags':flags,'compiler':subprocess.check_output(['g++','--version'],text=True).splitlines()[0],'cpu':2,'trials':3,'warmups':1,'nqueries':200000,'component_sha256':{v:hashlib.sha256(s.encode()).hexdigest() for v,s in variants.items()},'header_sha256':hashlib.sha256(header.encode()).hexdigest(),'quad_sha256':hashlib.sha256(quad.encode()).hexdigest(),'bench_sha256':hashlib.sha256(bench.encode()).hexdigest(),'checks':'All scalar/AVX2 rank/below/route/select checks, sentinel boundaries, shift30, size32 and rebuilding passed.','cases':raw},indent=2))

