#ifndef QUAD_BIT_VECTOR_HPP
#define QUAD_BIT_VECTOR_HPP

#include <algorithm>
#include <array>
#include <bit>
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <vector>
#if defined(__x86_64__) || defined(__i386__)
#include <immintrin.h>
#endif

struct QuadBitVector {
	struct Block {
		std::uint64_t low = 0, high = 0;
		std::array<int, 4> prefix{};
	};
	int n;
	std::vector<Block> blocks;

#if defined(__x86_64__) || defined(__i386__)
	__attribute__((target("avx2"))) static void pack_avx2(const std::uint32_t *a, int n, int shift, Block *blocks) {
		auto low_shift = _mm_cvtsi32_si128(31 - shift), high_shift = _mm_cvtsi32_si128(30 - shift);
		for (int w = 0; w < (n >> 6) + bool(n & 63); ++w) {
			int start = w * 64;
			std::uint64_t low = 0, high = 0;
			int length = std::min(64, n - start), j = 0;
			for (; j + 8 <= length; j += 8) {
				auto x = _mm256_loadu_si256(reinterpret_cast<const __m256i *>(a + start + j));
				low |= std::uint64_t(_mm256_movemask_ps(_mm256_castsi256_ps(_mm256_sll_epi32(x, low_shift)))) << j;
				high |= std::uint64_t(_mm256_movemask_ps(_mm256_castsi256_ps(_mm256_sll_epi32(x, high_shift)))) << j;
			}
			for (; j < length; ++j) {
				low |= std::uint64_t((a[start + j] >> shift) & 1) << j;
				high |= std::uint64_t((a[start + j] >> (shift + 1)) & 1) << j;
			}
			blocks[w].low = low;
			blocks[w].high = high;
		}
		blocks[n >> 6].low = n & 63 ? blocks[n >> 6].low : 0;
		blocks[n >> 6].high = n & 63 ? blocks[n >> 6].high : 0;
	}
#endif
	explicit QuadBitVector(int n = 0) : n(n), blocks((n >> 6) + 1) {}
	void build(const std::vector<std::uint32_t> &a, int shift) {
		assert(a.size() == std::size_t(n) && 0 <= shift && shift <= 30);
		[[maybe_unused]] bool vectorized = false;
#if defined(__x86_64__) || defined(__i386__)
		vectorized = n >= 64 && __builtin_cpu_supports("avx2");
		if (vectorized) pack_avx2(a.data(), n, shift, blocks.data());
#endif
		std::array<int, 4> counts{};
		for (int w = 0; w < static_cast<int>(blocks.size()); ++w) {
			std::uint64_t low = 0, high = 0;
			int start = w * 64, length = std::min(64, n - start);
			if (vectorized) low = blocks[w].low, high = blocks[w].high;
			else
				for (int j = 0; j < length; ++j) {
					low |= std::uint64_t((a[start + j] >> shift) & 1) << j;
					high |= std::uint64_t((a[start + j] >> (shift + 1)) & 1) << j;
				}
			blocks[w] = {low, high, counts};
			int c1 = std::popcount(low & ~high), c2 = std::popcount(~low & high), c3 = std::popcount(low & high);
			counts[0] += length - c1 - c2 - c3;
			counts[1] += c1;
			counts[2] += c2;
			counts[3] += c3;
		}
	}
	std::uint64_t mask(const Block &b, int digit) const {
		return ((digit & 1) ? b.low : ~b.low) & ((digit & 2) ? b.high : ~b.high);
	}

	int rank(int r, int digit) const {
		const auto &b = blocks[r >> 6];
		return b.prefix[digit] + std::popcount(mask(b, digit) & ((std::uint64_t(1) << (r & 63)) - 1));
	}
	int below(int r, int digit) const {
		if (!digit) return 0;
		if (digit == 1) return rank(r, 0);
		if (digit == 3) return r - rank(r, 3);
		const auto &b = blocks[r >> 6];
		return b.prefix[0] + b.prefix[1] + std::popcount(~b.high & ((std::uint64_t(1) << (r & 63)) - 1));
	}
	std::array<int, 4> ranks(int r) const {
		const auto &b = blocks[r >> 6];
		std::uint64_t m = (std::uint64_t(1) << (r & 63)) - 1;
		std::array<int, 4> a;
		a[1] = b.prefix[1] + std::popcount(b.low & ~b.high & m);
		a[2] = b.prefix[2] + std::popcount(~b.low & b.high & m);
		a[3] = b.prefix[3] + std::popcount(b.low & b.high & m);
		a[0] = r - a[1] - a[2] - a[3];
		return a;
	}
};

#endif

benchmark.text:
#ifndef WM_OPT_HEADER
#define WM_OPT_HEADER "data_structure/wavelet_matrix.hpp"
#endif
#include WM_OPT_HEADER
#include <chrono>
#include <cstdlib>
#include <cstdint>
#include <iostream>
#include <random>
#include <string>

struct Query {
	int l, r, k;
	std::int64_t x, y;
};

template <class T>
void run(int n, int q, int mode, int length, const std::string &op, unsigned seed) {
	std::mt19937_64 random(seed);
	std::vector<T> a(n);
	for (auto &x : a) {
		if (mode == 1) x = T(random() % 256);
		else if (mode == 2) x = T(random());
		else if (mode == 5) x = T(7);
		else if (mode == 6) x = T(random() % 2);
		else if (mode == 7) x = T(random() % 4096);
		else if (mode == 8) x = T(2 * (random() % 1000000000));
		else if (mode >= 9) x = T(random() % (mode == 9 ? 512 : mode == 10 ? 1024 : mode == 11 ? 16384 : 65536));
		else x = T(random() % 1000000000);
	}
	if (mode == 3 || mode == 4) std::sort(a.begin(), a.end());
	if (mode == 4) std::reverse(a.begin(), a.end());
	std::vector<Query> queries(q);
	for (auto &z : queries) {
		z.l = random() % n;
		z.r = random() % n;
		if (z.l > z.r) std::swap(z.l, z.r);
		++z.r;
		if (length) z.r = std::min(n, z.l + 1 + int(random() % length));
		z.k = random() % (z.r - z.l);
		z.x = std::int64_t(a[random() % n]);
		z.y = std::int64_t(a[random() % n]);
		if (mode == 8 && (random() & 1)) ++z.x;
		if (z.x > z.y) std::swap(z.x, z.y);
	}
	std::uint64_t checksum = 0;
	auto add = [&](auto value) {
		__uint128_t x = __uint128_t(value);
		checksum = (checksum ^ std::uint64_t(x) ^ std::uint64_t(x >> 64)) * 0x9e3779b97f4a7c15;
	};
	std::optional<WaveletMatrix<T>> wm;
	if (op != "build" && op != "eager") wm.emplace(a);
	if (op == "small" || op == "large" || op == "sum") wm->prepare_sum();
	auto start = std::chrono::steady_clock::now();
	if (op == "build" || op == "eager") {
		if (op == "build") wm.emplace(a);
		else wm.emplace(a, true);
		add(wm->size());
	} else if (op == "prepare") wm->prepare_sum(), add(wm->range_sum(0, n));
	else if (op == "kth") for (auto z : queries) add(wm->kth_smallest(z.l, z.r, z.k));
	else if (op == "freq") for (auto z : queries) add(wm->range_freq(z.l, z.r, T(z.x)));
	else if (op == "between") for (auto z : queries) add(wm->range_freq(z.l, z.r, T(z.x), T(z.y)));
	else if (op == "count") for (auto z : queries) add(wm->count(z.l, z.r, T(z.x)));
	else if (op == "prev") for (auto z : queries) { auto x = wm->prev_value(z.l, z.r, T(z.x)); add(x ? __int128_t(*x) : -13); }
	else if (op == "next") for (auto z : queries) { auto x = wm->next_value(z.l, z.r, T(z.x)); add(x ? __int128_t(*x) : -17); }
	else if (op == "small") for (auto z : queries) add(wm->sum_smallest(z.l, z.r, z.k));
	else if (op == "large") for (auto z : queries) add(wm->sum_largest(z.l, z.r, z.k));
	else if (op == "sum") for (auto z : queries) add(wm->range_sum(z.l, z.r));
	else if (op == "select") for (auto z : queries) add(wm->select(T(z.x), 0));
	else if (op == "access") for (auto z : queries) add(wm->access(z.l));
	else std::exit(2);
	double ms = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - start).count();
	std::cout.precision(12);
	std::cout << "{\"ms\":" << ms << ",\"checksum\":\"" << checksum << "\"}\n";
}

int main(int argc, char **argv) {
	if (argc != 8) return 2;
	int n = std::atoi(argv[1]), q = std::atoi(argv[2]), mode = std::atoi(argv[3]), length = std::atoi(argv[4]);
	if (n <= 0 || q <= 0 || mode < 0 || mode > 12 || length < 0) return 2;
	unsigned seed = unsigned(std::stoul(argv[7]));
	if (std::string(argv[6]) == "32") run<std::int32_t>(n, q, mode, length, argv[5], seed);
	else run<std::int64_t>(n, q, mode, length, argv[5], seed);
}

